package com.paylens.backend.controller;
import com.paylens.backend.dto.*; import com.paylens.backend.model.GovernanceStatus; import com.paylens.backend.service.GovernanceService; import jakarta.validation.Valid; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/decisions") public class DecisionController { private final GovernanceService service; public DecisionController(GovernanceService service){this.service=service;} @GetMapping public Map<String,Object> list(@RequestParam(required=false) GovernanceStatus status,@RequestParam(defaultValue="50") int limit){return Map.of("decisions",service.list(status,Math.min(Math.max(limit,1),100)));} @GetMapping("/{id}") public DecisionDetailResponse detail(@PathVariable String id){return service.detail(id);}@PostMapping("/{id}/approve") public GovernanceResponse approve(@PathVariable String id,@Valid @RequestBody ReviewRequest request){return service.review(id,request,true);}@PostMapping("/{id}/reject") public GovernanceResponse reject(@PathVariable String id,@Valid @RequestBody ReviewRequest request){return service.review(id,request,false);} }
